#!/usr/bin/env python3
import csv, gzip, io, json, os, re, sys
from datetime import datetime, timedelta, timezone, date
from fractions import Fraction
from decimal import Decimal
from zoneinfo import ZoneInfo

UTC = timezone.utc
EPOCH = datetime(1970, 1, 1, tzinfo=UTC)


def read_text(path):
    with open(path, 'rb') as f:
        data = f.read()
    if data[:2] == b'\x1f\x8b':
        data = gzip.decompress(data)
    return data.decode('utf-8-sig').replace('\r\n', '\n').replace('\r', '\n')


def lines_of(path):
    return [l for l in read_text(path).split('\n') if l.strip() != '']


def to_epoch(dt):
    return int((dt - EPOCH).total_seconds())


def local_to_epoch(naive, tz, want_dst=None, first=True):
    cands = []
    for fold in (0, 1):
        a = naive.replace(tzinfo=tz, fold=fold)
        back = a.astimezone(UTC).astimezone(tz).replace(tzinfo=None)
        if back == naive:
            cands.append(a)
    if not cands:
        return to_epoch(naive.replace(tzinfo=tz, fold=0))
    if len(cands) == 2 and cands[0].utcoffset() != cands[1].utcoffset():
        if want_dst is not None:
            for a in cands:
                if bool(a.dst()) == want_dst:
                    return to_epoch(a)
        return to_epoch(cands[0])
    return to_epoch(cands[0])


def parse_iso(s):
    s = s.strip()
    if s.endswith('Z'):
        s = s[:-1] + '+00:00'
    return datetime.fromisoformat(s)


def parse_time_of_day(s):
    s = s.strip()
    m = re.match(r'^(\d{1,2}):(\d{2})(?::(\d{2}))?\s*([AaPp][Mm])?$', s)
    h, mi, se, ap = int(m[1]), int(m[2]), int(m[3] or 0), m[4]
    if ap:
        h = h % 12 + (12 if ap.upper() == 'PM' else 0)
    return h, mi, se


# ---- format readers: yield (punch_id, emp, dir, epoch) ----

def read_abbr_csv(path, tz):
    header = None
    for line in lines_of(path):
        row = next(csv.reader([line]))
        row = [c.strip() for c in row]
        if 'Badge' in row and 'Punch' in row:
            header = row
            continue
        if header is None:
            continue
        r = dict(zip(header, row))
        mo, d, y = map(int, r['Date'].split('/'))
        h, mi, se = parse_time_of_day(r['Time'])
        naive = datetime(y, mo, d, h, mi, se)
        z = r.get('Zone', '').upper()
        want = True if z.endswith('DT') else (False if z.endswith('ST') else None)
        yield r['Record'], r['Badge'], r['Punch'].upper(), local_to_epoch(naive, tz, want)


def read_epoch_jsonl(path, tz):
