            schema = int(o['schema'])
            continue
        if o.get('heartbeat'):
            continue
        if schema == 2:
            if 'punch_id' not in o:
                continue
            ts = int(o['epoch_ms']) // 1000
            yield str(o['punch_id']), o['employee'], str(o['direction']).upper(), ts
        else:
            if 'id' not in o:
                continue
            if 'ts' in o:
                ts = int(float(o['ts']))
            else:
                ts = int(o['ts_ms']) // 1000
            yield str(o['id']), o['emp'], str(o['dir']).upper(), ts


def read_offset_csv(path, tz):
