    rd = csv.DictReader(ls, delimiter=';', quotechar='"')
    for r in rd:
        r = {k.strip(): v for k, v in r.items()}
        d = 'IN' if r['event'].strip() == 'clock_in' else 'OUT'
        yield r['punch_id'], r['employee'], d, to_epoch(parse_iso(r['timestamp']))


def std_offset(tz, day):
    dt = datetime(day.year, day.month, day.day, 12, tzinfo=tz)
    return dt.utcoffset() - (dt.dst() or timedelta(0))


def read_legacy(path, tz):
    off = None
    for line in read_text(path).split('\n'):
        if not line.strip():
            continue
        t = line[0]
        if t == 'H':
            m = re.match(r'^[+-]\d{4}$', line[13:18].strip())
            if m:
                s = line[13:18]
                off = timedelta(hours=int(s[1:3]), minutes=int(s[3:5]))
                if s[0] == '-':
                    off = -off
            else:
                off = None
        elif t == 'D':
            pid = line[1:9]
            badge = line[9:15].strip()
            dr = 'IN' if line[15] == 'I' else 'OUT'
            n = datetime.strptime(line[16:30], '%Y%m%d%H%M%S')
            o = off if off is not None else std_offset(tz, n.date())
            ts = to_epoch((n - o).replace(tzinfo=UTC))
            yield pid, 'E' + badge, dr, ts


