        h, mi = map(int, r['Uhrzeit'].split(':')[:2])
        z = r.get('Zeitzone', '').upper()
        want = True if z == 'MESZ' else (False if z == 'MEZ' else None)
        yield r['Nr'], r['Ausweis'], 'IN' if r['Buchung'] == 'K' else 'OUT', \
            local_to_epoch(datetime(y, mo, d, h, mi), tz, want)


