        n = datetime.strptime(r['local_time'], '%Y-%m-%d %H:%M:%S')
        yield r['punch_ref'], r['employee_id'], r['direction'].upper(), local_to_epoch(n, tz, True)


def read_local_jsonl(path, tz):
