            continue
        n = datetime.strptime(p['at'], '%Y-%m-%d %H:%M:%S')
        pid = p['id']
        pid = str(int(pid)) if isinstance(pid, (int, float)) else str(pid)
        yield pid, p['badge'], str(p['type']).upper(), local_to_epoch(n, tz, True)


