    punches = {}  # (site, id) -> [emp, dir, ts]
    ever = set()
    for site in sorted(sites):
        d = os.path.join(inp, 'exports', site)
        if not os.path.isdir(d):
            continue
        reader = READERS[sites[site]['format'].strip()]
        for root, _, files in os.walk(d):
            for fn in sorted(files):
                for pid, emp, dr, ts in reader(os.path.join(root, fn), zones[site]):
                    key = (site, str(pid))
                    ever.add(key)
                    if key not in punches:
                        punches[key] = [emp.strip(), dr, ts]

    # 2. corrections
    corr = []
    cdir = os.path.join(inp, 'corrections')
