        for fn in sorted(os.listdir(cdir)):
            p = os.path.join(cdir, fn)
            if os.path.isfile(p):
                for line_rows in [list(csv.DictReader(lines_of(p)))]:
                    for r in line_rows:
                        corr.append({k.strip(): (v or '').strip() for k, v in r.items()})
    corr = [c for c in corr if parse_iso(c['issued_at']) <= cutoff]
    corr.sort(key=lambda c: (parse_iso(c['issued_at']), c['correction_id']))
    applied = 0
    for c in corr:
        key = (c['site'], c['punch_id'])
        a = c['action'].lower()
        if a == 'void':
            if key in punches:
                del punches[key]
                applied += 1
        elif a == 'set':
            if key in punches:
                punches[key][2] = to_epoch(parse_iso(c['time']))
                applied += 1
        elif a == 'add':
            if key not in ever:
                ever.add(key)
                punches[key] = [c['employee'], c['type'].upper(), to_epoch(parse_iso(c['time']))]
                applied += 1

    byemp = {}
    for (site, pid), (emp, dr, ts) in punches.items():
        if emp in emp_home:
            byemp.setdefault(emp, []).append((ts, 0 if dr == 'OUT' else 1, site, pid, dr))

    def rnd(ts, site):
        tz = zones[site]
        off = datetime.fromtimestamp(ts, UTC).astimezone(tz).utcoffset()
        loc = ts + int(off.total_seconds())
        rem = loc % 360
        delta = -rem if rem < 180 else 360 - rem
        return ts + delta

    def workday(ts, emp):
        return datetime.fromtimestamp(ts, UTC).astimezone(zones[emp_home[emp]]).date()

    stats = {e['employee_id']: dict(shifts=0, paid=0, ot=0, night=0, gross=Fraction(0)) for e in employees}
    exc = dict(open_shifts=0, orphan_outs=0, duplicates_dropped=0, corrections_applied=applied)

    for emp, lst in byemp.items():
        lst.sort(key=lambda x: (x[0], x[1], x[2], x[3]))
        kept = []
        last = None
        for ts, _, site, pid, dr in lst:
            r = rnd(ts, site)
            if last is not None and last[1] == dr and ts - last[0] <= 300:
                if pstart <= workday(r, emp) <= pend:
                    exc['duplicates_dropped'] += 1
                continue
            last = (ts, dr)
            kept.append((r, dr, site, ts))
        # 5. pair
        shifts = []
        pending = None
        def close_open():
            if pending is not None and pstart <= workday(pending[0], emp) <= pend:
                exc['open_shifts'] += 1
        for k in kept:
            r, dr, site, ts = k
            if dr == 'IN':
                close_open()
                pending = k
            else:
                if pending is not None and r - pending[0] <= 16 * 3600:
                    shifts.append((pending, k))
                    pending = None
                else:
                    close_open()
                    pending = None
                    if pstart <= workday(r, emp) <= pend:
                        exc['orphan_outs'] += 1
        close_open()

        # 7/8 minutes
        items = []
        for i, o in shifts:
            wd = workday(i[0], emp)
            if not (pstart <= wd <= pend):
                continue
            worked = max(0, (o[0] - i[0]) // 60)
            paid = worked - 30 if worked > 360 else worked
            tz = zones[i[2]]
            night = 0
            t = i[0]
            while t < o[0]:
                h = datetime.fromtimestamp(t, UTC).astimezone(tz).hour
                if h >= 22 or h < 6:
                    night += 1
                t += 60
            night = min(night, paid)
            items.append([i[0], wd, paid, night, 0])
        items.sort(key=lambda x: x[0])
        daily = {}
        rem = []
        for it in items:
            used = daily.get(it[1], 0)
            dot = max(0, used + it[2] - max(used, 480))
            daily[it[1]] = used + it[2]
            it[4] = dot
            rem.append(it[2] - dot)
        weekly = {}
        for it, reg in zip(items, rem):
            wk = it[1] - timedelta(days=it[1].weekday())
            used = weekly.get(wk, 0)
            wot = max(0, used + reg - max(used, 2400))
            weekly[wk] = used + reg
            it[4] += wot
            rs = rates.get(emp, [])
            rate = None
            for eff, v in rs:
                if eff <= it[1]:
                    rate = v
            if rate is None and rs:
                rate = rs[0][1]
            rate = rate or Fraction(0)
            regular = it[2] - it[4]
            pay = rate * (regular + Fraction(3, 2) * it[4]) / 60 + rate * Fraction(15, 100) * it[3] / 60
            s = stats[emp]
            s['shifts'] += 1
            s['paid'] += it[2]
            s['ot'] += it[4]
            s['night'] += it[3]
            s['gross'] += pay

    out_emp = {}
    tot = dict(shifts=0, paid_minutes=0, overtime_minutes=0, night_minutes=0)
    totg = 0
    for e in employees:
        s = stats[e['employee_id']]
        cents = ((s['gross'] * 100) + Fraction(1, 2)).__floor__()
        out_emp[e['employee_id']] = dict(shifts=s['shifts'], paid_minutes=s['paid'], overtime_minutes=s['ot'],
                                         night_minutes=s['night'], gross='%d.%02d' % (cents // 100, cents % 100))
        tot['shifts'] += s['shifts']; tot['paid_minutes'] += s['paid']
        tot['overtime_minutes'] += s['ot']; tot['night_minutes'] += s['night']
        totg += cents
    tot['gross'] = '%d.%02d' % (totg // 100, totg % 100)
    res = dict(period=dict(start=period['start'], end=period['end']), employees=out_emp, exceptions=exc, totals=tot)
    with open(outp, 'w') as f:
        json.dump(res, f, indent=1)


main()
